<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    notifier.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(user, Message.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">welcome</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(user));</span></span>
